const input = require("fs").readFileSync(0, "utf8");

function findAnagrams(s, p) {
  const A = "a".charCodeAt(0);
  const need = new Array(26).fill(0);
  const window = new Array(26).fill(0);
  for (let i = 0; i < p.length; i++) {
    need[p.charCodeAt(i) - A]++;
  }
  const m = p.length;
  const starts = [];
  for (let i = 0; i < s.length; i++) {
    window[s.charCodeAt(i) - A]++;
    if (i >= m) {
      window[s.charCodeAt(i - m) - A]--;
    }
    if (i >= m - 1 && window.every((count, k) => count === need[k])) {
      starts.push(i - m + 1);
    }
  }
  return starts;
}

const [s, p] = input.trim().split(/\s+/);
const starts = findAnagrams(s, p);
console.log(starts.length > 0 ? starts.join(" ") : "none");

