package main

import (
	"fmt"
	"strconv"
	"strings"
)

func findAnagrams(s, p string) []int {
	// Arrays (not slices) can be compared with ==.
	var need, window [26]int
	for i := 0; i < len(p); i++ {
		need[p[i]-'a']++
	}
	m := len(p)
	var starts []int
	for i := 0; i < len(s); i++ {
		window[s[i]-'a']++
		if i >= m {
			window[s[i-m]-'a']--
		}
		if i >= m-1 && window == need {
			starts = append(starts, i-m+1)
		}
	}
	return starts
}

func main() {
	var s, p string
	fmt.Scan(&s, &p)
	starts := findAnagrams(s, p)
	if len(starts) == 0 {
		fmt.Println("none")
		return
	}
	parts := make([]string, len(starts))
	for i, start := range starts {
		parts[i] = strconv.Itoa(start)
	}
	fmt.Println(strings.Join(parts, " "))
}

