import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

// Adds delta to the count of the letter at text[i].
function bump(counts: number[], text: string, i: number, delta: number): void {
  const k = text.charCodeAt(i) - "a".charCodeAt(0);
  counts[k] = (counts[k] ?? 0) + delta;
}

function findAnagrams(s: string, p: string): number[] {
  const need: number[] = new Array<number>(26).fill(0);
  const window: number[] = new Array<number>(26).fill(0);
  for (let i = 0; i < p.length; i++) {
    bump(need, p, i, 1);
  }
  const m = p.length;
  const starts: number[] = [];
  for (let i = 0; i < s.length; i++) {
    bump(window, s, i, 1);
    if (i >= m) {
      bump(window, s, i - m, -1);
    }
    if (i >= m - 1 && window.every((count, k) => count === need[k])) {
      starts.push(i - m + 1);
    }
  }
  return starts;
}

const [s = "", p = ""] = input.trim().split(/\s+/);
const starts = findAnagrams(s, p);
console.log(starts.length > 0 ? starts.join(" ") : "none");
